    if(has('chunk'))[1/3,2/3].forEach(v=>s+=`<line x1="${f1(lerp(lx0,lx1,v))}" x2="${f1(lerp(lx0,lx1,v))}" y1="${ly-7}" y2="${ly+7}" style="stroke:var(--ink);stroke-width:1.4"/>`);
