/* a five-point star path centred on (cx,cy) */
function PT_star(cx,cy,r){let d='';for(let i=0;i<10;i++){const a=-Math.PI/2+i*Math.PI/5,rr=i%2?r*.45:r;d+=(i?'L':'M')+f1(cx+Math.cos(a)*rr)+' '+f1(cy+Math.sin(a)*rr)}return d+'Z'}
/* =============== 4.2 CBT, coaching & adult support =============== */
const TH_STEPS=[
 {from:0,at:.07,k:'Before therapy',t:'The avoidance loop',
  txt:`A common way to describe the problem CBT targets: a task feels too big ("I'll do it later"), that brings a wave of overwhelm, the task is avoided, and the relief of avoiding it makes avoiding more likely next time, while unfinished tasks pile up. The loop is an illustration. The trial that made CBT for adult ADHD widely known enrolled 86 adults who were already taking medication but still had significant symptoms, and compared 12 individual CBT sessions with an attention-matched control: relaxation plus educational support. <sup class="c" data-ref="Safren2010" title="Source 385"><a href="/adhd/sources/#src-Safren2010">385</a></sup>`,
  pt:`Putting things off is not laziness. Avoiding a task gives quick relief, and that relief keeps the habit going.`,
  hook:`Safren 2010 (JAMA): 86 medication-treated adults with persistent symptoms; CBT vs an attention-matched relaxation-plus-education control.`},
 {from:.14,at:.25,k:'Sessions 1–4 · core module 1',t:'Organise and plan',
  txt:`The first module combines psychoeducation with organising and planning: one calendar and one task list, problem-solving, and breaking big tasks into steps small enough to start. It takes 4 sessions. In the planner, the essay becomes outline, draft and check on different days, and Sunday evening becomes the weekly planning slot. <sup class="c" data-ref="Safren2010" title="Source 385"><a href="/adhd/sources/#src-Safren2010">385</a></sup>`,
  pt:`Everything goes in one calendar and one list, and big jobs are cut into small first steps.`,
  hook:`Safren CBT core modules: organise & plan (4 sessions) → reduce distractibility (2) → cognitive restructuring (3). <sup class="c" data-ref="Safren2010" title="Source 385"><a href="/adhd/sources/#src-Safren2010">385</a></sup>`},
 {from:.36,at:.43,k:'Sessions 5–6 · core module 2',t:'Reduce distractibility',
  txt:`The second core module, 2 sessions, works on distractibility. The planner shows one way this is often practised: work in timed blocks sized to the person's real attention span, with stray thoughts parked on a note to deal with later. The exact techniques are in the manual; the drawing is an illustration. <sup class="c" data-ref="Safren2010" title="Source 385"><a href="/adhd/sources/#src-Safren2010">385</a></sup>`,
  pt:`Work in short, timed blocks you can actually finish, and park distractions on a note for later.`,
  hook:`Two sessions on distractibility sit between planning and cognitive restructuring in Safren's protocol.`},
 {from:.5,at:.59,k:'Sessions 7–9 · core module 3',t:'Adaptive thinking',
  txt:`Cognitive restructuring takes 3 sessions: noticing the thought that fuels avoidance and testing it. In the loop, "I'll do it later" is rewritten as "Start with 10 minutes", which turns the next arrow from avoidance into a first step. Group meta-cognitive therapy, which focuses on time management, organisation and planning, beat supportive group therapy in 88 adults (odds ratio for response 5.41). <sup class="c" data-ref="Safren2010,Solanto2010" title="Source 385,413"><a href="/adhd/sources/#src-Safren2010">385,413</a></sup>`,
  pt:`Catch the thought that says "later", and swap it for one that gets you started.`,
  hook:`Meta-cognitive group therapy vs supportive group: OR for response 5.41 (95% CI 1.77 to 16.55). <sup class="c" data-ref="Solanto2010" title="Source 413"><a href="/adhd/sources/#src-Solanto2010">413</a></sup>`},
 {from:.68,at:.76,k:'Sessions 10–12 · optional and ending',t:'Procrastination and relapse prevention',
  txt:`Optional sessions cover procrastination and a session with a family member, and the course ends with relapse prevention: which skills to keep, and what to do when old habits return. A meta-analysis found adult psychosocial treatment gains maintained for at least 12 months. <sup class="c" data-ref="Safren2010,LopezPinar2018" title="Source 261,385"><a href="/adhd/sources/#src-Safren2010">261,385</a></sup>`,
  pt:`The last sessions plan for bad weeks, so the skills survive after therapy ends.`,
  hook:`Adult psychosocial treatment: gains maintained ≥12 months; group DBT trials and active-control trials gave smaller effects. <sup class="c" data-ref="LopezPinar2018" title="Source 261"><a href="/adhd/sources/#src-LopezPinar2018">261</a></sup>`},
 {from:.84,at:.95,k:'After 12 sessions',t:'Responders: twice as many with CBT',
  txt:`On the ADHD rating scale scored by a blind assessor, CBT beat the comparison arm (difference −4.63, 95% CI −8.30 to −0.96). Responders were 67% versus 33% (odds ratio 4.29), and on the clinician global impression 53% versus 23% (odds ratio 3.80). Gains were maintained at 6 and 12 months. These are group results in medicated adults; they cannot predict one person's response. <sup class="c" data-ref="Safren2010" title="Source 385"><a href="/adhd/sources/#src-Safren2010">385</a></sup>`,
  pt:`Adults with ADHD can benefit from CBT focused on planning, organising and handling distraction, especially alongside medicine.`,
  hook:`Adult CBT (Safren 2010): responders 67% vs 33% on the ADHD rating scale, 53% vs 23% on the CGI.`}
];
