    const blk=u<.4?['focus',u/.4]:u<.5?['break',(u-.4)/.1]:u<.9?['focus',(u-.5)/.4]:['break',(u-.9)/.1],R=34,X=cx+90,Y=gy-118;
    const a=Math.PI*2*clamp(blk[1]),c=blk[0]==='focus'?'var(--accent)':'var(--beh)';
