      const up=pts.filter(p=>p[0]<=h);if(up.length>1)s+=`<path d="${tr(up)}L${f1(X(up[up.length-1][0]))} ${L.by1}L${f1(X(6))} ${L.by1}Z" style="fill:var(--rx);opacity:.16"/><path d="${tr(up)}" style="fill:none;stroke:var(--rx);stroke-width:2.4"/>`;
