    s+=`<line x1="${f1(X(h))}" x2="${f1(X(h))}" y1="${L.by0-4}" y2="${L.ry+20}" style="stroke:var(--ink);stroke-width:1.2;opacity:.6"/><path d="M${f1(X(h)-5)} ${L.by0-10}h10l-5 7z" style="fill:var(--ink)"/>`;
