    $('#lvRead').innerHTML=`<span>Time <b>${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')}</b></span><span>Part of the day <b>${P.nt}</b></span>`+(cover?`<span>Schematic cover <b>${Math.round(cov(h)*100)}%</b></span>`:'');
